-- Catalogo Norvegia, versione 1 (NO-1).
-- GENERATO da scripts/seed-catalog.ts: non modificare a mano, rigenerare con `npx tsx scripts/seed-catalog.ts`.
-- Prerequisito: migrazioni supabase/migrations/20261106000100 … 20261106000500.
-- Idempotente: con la versione già pubblicata non scrive nulla e controlla solo i conteggi.
-- Tocca solo le tabelle del catalogo: nessun viaggio, nessun dato di auth.

begin;

on conflict (code) do nothing;

on conflict (release_id) do nothing;

on conflict (place_key) do nothing;

on conflict (iata) do nothing;

-- Contenuto della versione: si scrive solo se è ancora in bozza
do $seed$
begin
  if not exists (select 1 from public.catalog_releases where release_id = 'NO-1' and status = 'bozza') then
    raise notice 'Versione NO-1 già pubblicata: nessuna scrittura, solo controllo';
    return;
  end if;








end $seed$;

update public.catalog_releases set status = 'pubblicata', published_at = now() where release_id = 'NO-1' and status = 'bozza';

-- Controllo finale: se fallisce, la transazione si annulla
do $check$
declare
  v_n bigint;
begin
  if not exists (select 1 from public.countries where code = 'NO' and currency = 'NOK' and timezone = 'Europe/Oslo' and language = 'nb') then
    raise exception 'Nazione NO: valuta, fuso o lingua diversi da quelli del seed';
  end if;
  perform now() at time zone 'Europe/Oslo';
  if not exists (select 1 from public.catalog_releases where release_id = 'NO-1' and status = 'pubblicata') then
    raise exception 'Versione NO-1 non pubblicata';
  end if;
  select count(*) into v_n from public.regions where release_id = 'NO-1';
  if v_n <> 7 then raise exception 'regions (release_id = ''NO-1''): attese 7 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-1';
  if v_n <> 117 then raise exception 'places (release_id = ''NO-1''): attese 117 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_texts where release_id = 'NO-1';
  if v_n <> 117 then raise exception 'place_texts (release_id = ''NO-1''): attese 117 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_sources where release_id = 'NO-1';
  if v_n <> 394 then raise exception 'place_sources (release_id = ''NO-1''): attese 394 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.operators where release_id = 'NO-1';
  if v_n <> 2 then raise exception 'operators (release_id = ''NO-1''): attese 2 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.voyages where release_id = 'NO-1';
  if v_n <> 24 then raise exception 'voyages (release_id = ''NO-1''): attese 24 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.route_ports where release_id = 'NO-1';
  if v_n <> 35 then raise exception 'route_ports (release_id = ''NO-1''): attese 35 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_links where release_id = 'NO-1';
  if v_n <> 9 then raise exception 'place_links (release_id = ''NO-1''): attese 9 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-1' and category = 'porti';
  if v_n <> 35 then raise exception 'places (release_id = ''NO-1'' and category = ''porti''): attese 35 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-1' and coords_status = 'verificate';
  if v_n <> 72 then raise exception 'places (release_id = ''NO-1'' and coords_status = ''verificate''): attese 72 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-1' and official_url is not null;
  if v_n <> 29 then raise exception 'places (release_id = ''NO-1'' and official_url is not null): attese 29 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-1' and wikidata_qid is not null;
  if v_n <> 77 then raise exception 'places (release_id = ''NO-1'' and wikidata_qid is not null): attese 77 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'NO-1' and base_place_key is not null;
  if v_n <> 8 then raise exception 'places (release_id = ''NO-1'' and base_place_key is not null): attese 8 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places p join public.place_keys k on k.place_key = p.place_key where p.release_id = 'NO-1' and k.country_code <> 'NO';
  if v_n <> 0 then raise exception 'Chiavi di luogo registrate per un''altra nazione: %', v_n; end if;
  select count(*) into v_n from public.places p where p.release_id = 'NO-1' and not exists (select 1 from public.place_texts t where t.release_id = p.release_id and t.place_key = p.place_key and t.lang = 'it');
  if v_n <> 0 then raise exception 'Luoghi senza testo italiano: %', v_n; end if;
  raise notice 'Catalogo NO-1 pubblicato e controllato: 117 luoghi, 24 crociere, 35 porti in rotta';
end $check$;

commit;
